on note
  ignore_event($EVENT_ID)
  if (%key_pc[$EVENT_NOTE] < 0)
    exit
  end if
  inc($keys_down)
  %src_held[$EVENT_NOTE] := 1
  $dh_note := $EVENT_NOTE
  $dh_vel := $EVENT_VELOCITY
  call drum_hit
  if ($repeat > 0 and %pz_hold[%key_pc[$EVENT_NOTE]] = 0)
    if (%rep_vel[$EVENT_NOTE] = 0)
      inc($rep_n)
    end if
    %rep_vel[$EVENT_NOTE] := $EVENT_VELOCITY
    %rep_next[$EVENT_NOTE] := $tick + %rep_ticks[$repeat]
  end if
end on

on release
  if (%key_pc[$EVENT_NOTE] >= 0)
    if (%rep_vel[$EVENT_NOTE] > 0)
      %rep_vel[$EVENT_NOTE] := 0
      dec($rep_n)
    end if
    dec($keys_down)
    if ($keys_down < 0)
      $keys_down := 0
    end if
    %src_held[$EVENT_NOTE] := 0
    if (%src_n[$EVENT_NOTE] > 0)
      $rs_src := $EVENT_NOTE
      $rs_time := $rel_us
      call release_src
    end if
  end if
end on

on controller
  if ($CC_NUM = 64 and $use_pedal = 1)
    if (%CC[64] >= 64)
      $pedal := 1
    else
      if ($pedal = 1)
        $pedal := 0
        call pedal_up
      end if
    end if
  end if
  if ($CC_NUM = 120 or $CC_NUM = 123)
    $rs_time := 20000
    call release_all
  end if
  if ($CC_NUM = 1)
    $dyn := %CC[1]
    $dyn_knob := %CC[1]
    call calc_dyn
    call update_dyn
  end if
end on

on listener
  if ($NI_SIGNAL_TYPE = $NI_SIGNAL_TIMER_BEAT)
    inc($tick)
    if ($pq_n > 0)
      call process_pending
    end if
    if ($repeat > 0 and $rep_n > 0)
      $rp_k := 0
      while ($rp_k < 128)
        if (%rep_vel[$rp_k] > 0 and $tick >= %rep_next[$rp_k])
          $dh_note := $rp_k
          $dh_vel := %rep_vel[$rp_k]
          call drum_hit
          %rep_next[$rp_k] := $tick + %rep_ticks[$repeat]
        end if
        inc($rp_k)
      end while
    end if
  end if
end on

